<script setup>
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { documentApi } from '@/services/document.service'; import { documentTypeLabel } from '@/services/terminology'
const props = defineProps({ documentType: { type: String, default: '' }, basePath: { type: String, default: '/dashboard/courses' } }); const route = useRoute(); const data = ref(null); const error = ref('')
onMounted(async () => { try { data.value = await documentApi.courseYears(route.params.courseId, props.documentType) } catch { error.value = 'โหลดข้อมูลรายวิชาไม่สำเร็จ' } })
</script>
<template><section class="page-panel"><p v-if="error" class="form-error">{{ error }}</p><div v-else-if="!data" class="loading-state">กำลังโหลดปีการศึกษา…</div><template v-else><div class="panel__header"><div><p class="eyebrow">{{ data.course.code }}<span v-if="documentType"> · {{ documentTypeLabel(documentType) }}</span></p><h1>{{ data.course.name }}</h1><p>{{ data.course.description }}</p></div><RouterLink class="button button--ghost" to="/dashboard/home">กลับหน้าหลัก</RouterLink></div><div v-if="data.years.length" class="catalog-grid"><article v-for="year in data.years" :key="year.academicYear" class="material-card academic-year-card"><span class="material-meta">ปีการศึกษา</span><h2>{{ year.academicYear }}</h2><p>{{ year.documentCount }} เอกสารที่เผยแพร่</p><RouterLink class="text-link" :to="`${basePath}/${data.course.id}/years/${year.academicYear}`">ดูภาคเรียนและเอกสาร →</RouterLink></article></div><div v-else class="empty-state"><h2>ยังไม่มีเอกสารที่เผยแพร่</h2><p>ระบบแสดงเฉพาะข้อมูลที่ผ่านการตรวจสอบแล้ว</p></div></template></section></template>
